<?php
 namespace Pterodactyl\Jobs\Dezerx; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Pterodactyl\Services\Dezerx\Minecraft\MapRenderer; use Pterodactyl\Services\Dezerx\Minecraft\RegionFile; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class RenderRegionMap extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 600; public int $tries = 1; public function __construct( public Server $server, public string $path, public string $destination, ) { $this->queue = 'standard'; } public function middleware(): array { return [(new WithoutOverlapping($this->destination))->dontRelease()]; } public function handle(): void { if (is_file($this->destination) && filesize($this->destination) > 0) { return; } $files = new ServerFiles($this->server); $file = RegionFile::fetch($files, $this->server->uuid, $this->path); if ($file === null) { Log::warning('Region could not be fetched for rendering', [ 'server' => $this->server->uuid, 'path' => $this->path, ]); return; } $chunks = RegionFile::index($file); if ($chunks === null) { return; } MapRenderer::render($file, $chunks, $this->destination); } } 